type Quantity<T extends number> = readonly [magnitude: T, unit: string];

/**
 * Determine the point at which a dropped object comes to rest on a frictionless surface.
 * @param x - The distance fallen by the object.
 * @param g - The acceleration due to gravity (approximately 9.81 m/s^2).
 */
function terminalVelocity(x: Quantity<number>, g: number): number {
  return Math.sqrt(2 * g * x.magnitude);
}
