/**
 * Given pairs of nodes with values, calculates the median absolute deviation of these values.
 *
 * @param pairs - Each pair contains two nodes and their respective values.
 * @returns The median absolute deviation of the values in all pairs.
 */
function medianAbsoluteDeviation(pairs: [number, number, number, number][]): number {
    // sort pairs by value of first node
    const sortedPairs = pairs.sort((a, b) => a[2] - b[2]);
    // get sorted array of node values
    const sortedValues = sortedPairs.map(pair => pair[2]);
    // calculate median of values
    const median = sortedValues[Math.floor(sortedValues.length / 2)];
    // calculate median absolute deviation
    const mad = sortedValues.reduce((a, b) => a + Math.abs(b - median), 0) / sortedValues.length;
    return mad;
}
